<span class="line"><span style="--shiki-light:#800000;--shiki-dark:#808080;">	&lt;</span><span style="--shiki-light:#800000;--shiki-dark:#569CD6;">patientgegevens_id</span><span style="--shiki-light:#800000;--shiki-dark:#808080;">&gt;</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">…</span><span style="--shiki-light:#800000;--shiki-dark:#808080;">&lt;/</span><span style="--shiki-light:#800000;--shiki-dark:#569CD6;">patientgegevens_id</span><span style="--shiki-light:#800000;--shiki-dark:#808080;">&gt;</span></span>
